#!/usr/bin/env node
// Checks a built dist/ against the SD webroot bundle contract of the DISC
// service (snowsky-disc-service docs/sd-webroot.md and
// scripts/webroot_bundle.py). The service publisher enforces the same rules;
// this check fails the build earlier and runs without a service checkout.
import { readdirSync, readFileSync, lstatSync } from 'node:fs'
import { join, relative, extname, sep } from 'node:path'

const ALLOWED = new Set([
  '.html',
  '.css',
  '.js',
  '.mjs',
  '.json',
  '.svg',
  '.png',
  '.jpg',
  '.jpeg',
  '.webp',
  '.ico',
  '.woff2',
  '.wasm',
])
const COMPONENT = /^[A-Za-z0-9_.-]{1,80}$/
const MAX_FILE = 4 * 1024 * 1024
const MAX_TOTAL = 16 * 1024 * 1024
const GENERATED = new Set(['compatibility.json', 'commands.json', 'queries.json', 'store.json', 'origins.json', 'READY'])
const MAX_FILES = 128 - GENERATED.size
const INLINE_SCRIPT = /<script\b(?![^>]*\bsrc=)[^>]*>\s*\S/is
const INLINE_STYLE = /<style\b[^>]*>\s*\S|\bstyle\s*=\s*["']/is
const INLINE_HANDLER = /\son[a-z]+\s*=\s*["']/i
const SCRIPT_URL = /javascript:/i
// index.html is served at /, so its own references must be root-absolute (the
// publisher rewrites them to /releases/<id>/); relative ones would miss.
const RELATIVE_DOCUMENT_REF = /\b(?:href|src)="(?!\/|https?:|#|mailto:)[^"]+"/i
const ROOT_ASSET =
  /["'(]\/(?!api\/|releases\/)(?:[A-Za-z0-9_.-]+\/)*[A-Za-z0-9_.-]+\.(?:js|mjs|css|json|svg|png|jpe?g|webp|ico|woff2|wasm)\b/

export function checkBundle(root) {
  const errors = []
  const files = []
  const walk = (dir) => {
    for (const entry of readdirSync(dir)) {
      const path = join(dir, entry)
      const info = lstatSync(path)
      if (info.isDirectory()) walk(path)
      else files.push({ path, name: relative(root, path).split(sep).join('/'), info })
    }
  }
  walk(root)
  const folded = new Set()
  let total = 0
  for (const { path, name, info } of files) {
    const parts = name.split('/')
    if (!info.isFile()) errors.push(`${name}: not a regular file`)
    if (!ALLOWED.has(extname(name).toLowerCase())) errors.push(`${name}: extension not allowed on the card`)
    if (parts.length > 4) errors.push(`${name}: deeper than 4 path components`)
    if (parts.some((part) => !COMPONENT.test(part) || part === '.' || part === '..'))
      errors.push(`${name}: name must match [A-Za-z0-9_.-]{1,80}`)
    if (GENERATED.has(name)) errors.push(`${name}: generated by the service publisher, must not come from the build`)
    if (info.size > MAX_FILE) errors.push(`${name}: larger than 4 MiB`)
    if (folded.has(name.toLowerCase())) errors.push(`${name}: case-insensitive name collision`)
    folded.add(name.toLowerCase())
    total += info.size
    const text = /\.(html|js|mjs|css)$/.test(name) ? readFileSync(path, 'utf8') : ''
    if (name.endsWith('.html')) {
      for (const [pattern, what] of [
        [INLINE_SCRIPT, 'inline script'],
        [INLINE_STYLE, 'inline style'],
        [INLINE_HANDLER, 'inline event handler'],
        [SCRIPT_URL, 'javascript: URL'],
      ]) {
        if (pattern.test(text)) errors.push(`${name}: ${what} is blocked by the gateway CSP`)
      }
      const relative = name === 'index.html' ? RELATIVE_DOCUMENT_REF.exec(text) : null
      if (relative)
        errors.push(`${name}: relative reference ${relative[0]} does not resolve from /; use a root-absolute path`)
    } else if (text) {
      const match = ROOT_ASSET.exec(text)
      if (match)
        errors.push(`${name}: root-absolute asset reference ${match[0].slice(1)} cannot resolve under /releases/<id>/`)
    }
  }
  if (!files.some((file) => file.name === 'index.html')) errors.push('index.html is missing')
  if (files.length > MAX_FILES)
    errors.push(`${files.length} files; at most ${MAX_FILES} leave room for the generated ones`)
  if (total > MAX_TOTAL) errors.push(`${total} bytes; the release limit is 16 MiB`)
  return { files: files.length, bytes: total, errors }
}

if (import.meta.url === `file://${process.argv[1]}`) {
  const root = process.argv[2] ?? 'dist'
  const result = checkBundle(root)
  for (const error of result.errors) console.error(`bundle: ${error}`)
  if (result.errors.length) process.exit(1)
  console.log(`bundle: ${result.files} files, ${result.bytes} bytes, SD contract satisfied`)
}
